const payload = $input.item.json.body ?? $input.item.json;
const lead = payload.lead ?? {};
const message = String(payload.message ?? '').trim();
if (!message) throw new Error('A chat message is required.');
const knowledge = `RenovateAI helps homeowners plan kitchen renovations, bathroom remodels, whole-home renovations, basements, additions, and similar projects. Typical project cost depends on scope, finishes, local labor, permits, and structural work. Do not quote a precise price or promise a timeline; encourage a consultation for a tailored estimate.`;
const prompt = `You are RenovateAI’s friendly renovation assistant. Answer FAQs using only the knowledge below. You may collect a lead conversationally, one or two missing details at a time. Never request payment or sensitive data. Return ONLY valid JSON exactly matching: {"reply": string, "leadUpdates": {"name"?:string,"email"?:string,"phone"?:string,"projectType"?:string,"budget"?:string,"location"?:string,"timeline"?:string,"description"?:string}, "isLeadComplete": boolean}. Only set isLeadComplete true when all eight fields are present across the current lead and updates.

Knowledge: ${knowledge}

Current collected lead: ${JSON.stringify(lead)}

Recent conversation: ${JSON.stringify(payload.history ?? [])}

Latest visitor message: ${message}`;
return [{json: {prompt}}];

const response = $input.item.json;
try {
  const body = typeof response.body === 'string' ? JSON.parse(response.body) : response.body;
  const text = body?.candidates?.[0]?.content?.parts?.[0]?.text;
  const chat = JSON.parse(text);
  if (typeof chat.reply !== 'string') throw new Error('Missing chat reply');
  return [{json: {response: {reply: chat.reply, leadUpdates: chat.leadUpdates ?? {}, isLeadComplete: chat.isLeadComplete === true}}}];
} catch {
  return [{json: {response: {reply: 'I’m having trouble responding right now. Please use the project form and our team will help.', leadUpdates: {}, isLeadComplete: false}}}];
}
